import * as React from "react"
import { cn } from "@/lib/utils"
import { Separator } from "@/components/ui/separator"
import { useRender } from "@base-ui/react/use-render"
import { mergeProps } from "@base-ui/react/merge-props"
import { cva, type VariantProps } from "class-variance-authority"

import "@/styles/data.styles.css"

function ItemGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      role="list"
      data-slot="item-group"
      className={cn(
        "group/item-group flex w-full flex-col gap-4 has-data-[size=sm]:gap-2.5 has-data-[size=xs]:gap-2",
        className
      )}
      {...props}
    />
  )
}

function ItemSeparator({ className, ...props }: React.ComponentProps<typeof Separator>) {
  return (
    <Separator
      data-slot="item-separator"
      orientation="horizontal"
      className={cn("my-2", className)}
      {...props}
    />
  )
}

const itemVariants = cva(
  "item-layout group/item flex w-full flex-wrap items-center border text-sm transition-colors duration-100 motion-reduce:transition-none",
  {
    variants: {
      variant: {
        default: "border-transparent",
        outline: "border-border",
        muted: "border-transparent bg-muted",
      },
      size: {
        default: "gap-2.5 px-3 py-2.5",
        sm: "gap-2.5 px-3 py-2.5",
        xs: "gap-2 px-2.5 py-2 in-data-[slot=dropdown-menu-content]:p-0",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Item({
  className,
  variant = "default",
  size = "default",
  render,
  ...props
}: useRender.ComponentProps<"div"> & VariantProps<typeof itemVariants>) {
  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(
      {
        className: cn(itemVariants({ variant, size, className })),
      },
      props
    ),
    render,
    state: {
      slot: "item",
      variant,
      size,
    },
  })
}

const itemMediaVariants = cva(
  "flex shrink-0 items-center justify-center gap-2 group-has-data-[slot=item-description]/item:translate-y-0.5 group-has-data-[slot=item-description]/item:self-start [&_svg]:pointer-events-none",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        icon: "[&_svg:not([class*='size-'])]:size-4",
        image:
          "size-10 overflow-hidden rounded-sm group-data-[size=sm]/item:size-8 group-data-[size=xs]/item:size-6 [&_img]:size-full [&_img]:object-cover",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

function ItemMedia({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof itemMediaVariants>) {
  return (
    <div
      data-slot="item-media"
      data-variant={variant}
      className={cn(itemMediaVariants({ variant, className }))}
      {...props}
    />
  )
}

function ItemContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-content"
      className={cn(
        "flex min-w-0 flex-1 flex-col gap-1 group-data-[size=xs]/item:gap-0 [&+[data-slot=item-content]]:flex-none",
        className
      )}
      {...props}
    />
  )
}

function ItemTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-title"
      className={cn(
        "line-clamp-1 flex w-fit items-center gap-2 text-sm leading-snug font-medium underline-offset-4",
        className
      )}
      {...props}
    />
  )
}

function ItemDescription({ className, ...props }: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="item-description"
      className={cn(
        "line-clamp-2 text-left text-sm leading-normal font-normal text-muted-foreground group-data-[size=xs]/item:text-xs [&>a]:underline [&>a]:underline-offset-4 [&>a:hover]:text-primary",
        className
      )}
      {...props}
    />
  )
}

function ItemActions({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div data-slot="item-actions" className={cn("flex items-center gap-2", className)} {...props} />
  )
}

function ItemHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-header"
      className={cn("flex basis-full items-center justify-between gap-2", className)}
      {...props}
    />
  )
}

function ItemFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-footer"
      className={cn("flex basis-full items-center justify-between gap-2", className)}
      {...props}
    />
  )
}

export {
  Item,
  ItemMedia,
  ItemContent,
  ItemActions,
  ItemGroup,
  ItemSeparator,
  ItemTitle,
  ItemDescription,
  ItemHeader,
  ItemFooter,
}

/* Data/list presentation. No virtual row, DnD, column width or editor height rules. */
@layer components {
  /* Consumers do not need the website global border reset. */
  .table-layout :is(thead, tbody, tfoot, tr, th, td),
  [data-slot="data-grid-table"] :is(thead, tbody, tfoot, tr, th, td) {
    border-color: var(--border);
  }
  .item-layout {
    border-radius: var(--radius, 0.625rem);
    font-size: calc(14 * var(--component-unit, 0.0625rem));
    line-height: calc(20 * var(--component-unit, 0.0625rem));
    outline: none;
  }
  .item-layout:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
    box-shadow: none;
  }
  .table-layout {
    color: var(--foreground);
  }
  .table-row-layout[data-state="selected"],
  .data-grid-row-layout[data-state="selected"] {
    background: var(--muted);
  }
  .data-grid-inline-control-layout:has(input:focus-visible),
  .data-grid-inline-control-layout:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: -2px;
    box-shadow: none;
  }
  .data-grid-edit-trigger-layout {
    outline: none;
  }
  .data-grid-edit-trigger-layout:focus-visible,
  .data-grid-filter-option-layout:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: -2px;
    box-shadow: none;
  }
  .data-grid-filter-option-layout {
    color: var(--foreground);
    min-height: calc(32 * var(--component-unit, 0.0625rem));
  }
  .rating-star-layout {
    display: block;
    flex-shrink: 0;
    padding: 0;
    border: 0;
    background: transparent;
    border-radius: 2px;
    outline: none;
  }
  button.rating-star-layout:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
    box-shadow: none;
    z-index: 1;
  }
  .rating-star-layout svg {
    pointer-events: none;
  }
  @media (hover: hover) {
    a.item-layout:hover,
    button.item-layout:hover,
    .table-row-layout:not([data-state="selected"]):hover,
    .data-grid-row-layout:not([data-state="selected"]):hover,
    .data-grid-edit-trigger-layout:not(:disabled):hover,
    .data-grid-filter-option-layout:hover {
      background: var(--muted);
    }
  }
  @media (pointer: coarse) {
    .data-grid-filter-option-layout {
      min-height: 44px;
    }
    /* Star targets expand in layout only outside measured grid cells. */
    [data-slot="rating"]:not([data-slot="data-grid-table"] [data-slot="rating"])
      button.rating-star-layout {
      min-width: 44px;
      min-height: 44px;
      display: grid;
      place-items: center;
    }
  }
  @media (forced-colors: active) {
    .item-layout:focus-visible,
    .data-grid-inline-control-layout:has(input:focus-visible),
    .data-grid-inline-control-layout:focus-visible,
    .data-grid-edit-trigger-layout:focus-visible,
    .data-grid-filter-option-layout:focus-visible,
    button.rating-star-layout:focus-visible {
      outline-color: Highlight;
    }
    .table-row-layout[data-state="selected"],
    .data-grid-row-layout[data-state="selected"] {
      background: Highlight;
      color: HighlightText;
    }
    [data-slot="rating-star-filled"] {
      color: Highlight;
      fill: Highlight;
    }
  }
}
